      thisD <- NULL
      for (jTild in allJ) {
        H <- paste0("H", j, ".j", ifelse(jTild == j, "Self", "NotSelf"), ".z", z)
        thisD <- cbind(thisD, dataList[[1]][[H]] / (1 - dataList[[1]][[paste0("hazNot", j)]]) *
          (dataList[[1]][[paste0("N", jTild)]] - dataList[[1]][[paste0("Q", jTild, "Haz")]]))
      }
      dat[[paste0("D.j", j, ".z", z)]] <- unlist(by(rowSums(thisD), dataList[[1]]$id, FUN = sum)) +
        dat[[paste0("F", j, ".z", z, ".t0")]] - dat[[paste0("margF", j, ".z", z, ".t0")]]
    }
  }
  return(dat)
}

estimateCensoring <- function(dataList,
                              adjustVars,
                              t0,
                              SL.ctime = NULL,
                              glm.ctime = NULL,
                              glm.family,
                              returnModels = FALSE,
                              verbose = TRUE,
                              gtol = 1e-3,
                              ...) {
  include <- !(dataList[[1]]$t == dataList[[1]]$ftime & dataList[[1]]$C != 1 &
    dataList[[1]]$t < t0) & !(dataList[[1]]$t == dataList[[1]]$ftime
  & dataList[[1]]$C == 1 & dataList[[1]]$t == t0)

  ## determine whether to use linear or logistic regression in GLM fit
  if (!is.null(glm.family)) {
    glm_family <- parse(text = paste0("stats::", glm.family, "()"))
  }

  # if no SL library is specified, the code defaults to the specific GLM form
  if (is.null(SL.ctime)) {
    if (!(any(c("glm", "speedglm") %in% class(glm.ctime)))) {
      if (!all(dataList[[1]]$C == 0)) {
        ctimeForm <- stats::as.formula(sprintf("%s ~ %s", "C", glm.ctime))
        ctimeMod <- fast_glm(
          reg_form = ctimeForm,
          data = dataList[[1]][include, ],
          family = eval(glm_family)
        )
        if (unique(class(ctimeMod) %in% c("glm", "lm"))) {
          ctimeMod <- cleanglm(ctimeMod)
        }
      } else {
        dataList <- lapply(dataList, function(x) {
          x$G_dC <- 1
          x
        })
        ctimeMod <- "No censoring observed"
        class(ctimeMod) <- "noCens"
      }

      suppressWarnings(
        Qmod <- SuperLearner::SuperLearner(
          Y = wideDataList[[1]][include, outcomeName],
          X = wideDataList[[1]][include, c("trt", names(adjustVars))],
          SL.library = SL.ftime,
          cvControl = cvControl,
          family = "binomial",
          verbose = verbose
        )
      )
      wideDataList <- lapply(wideDataList, function(x, whichJ, t) {
        suppressWarnings(
          x[[Qj.t]] <- x[[Nj.tm1]] + (1 - x[[Nj.tm1]] - x[[NnotJ.tm1]]) *
            predict(Qmod, newdata = x[, c("trt", names(adjustVars))], onlySL = TRUE)$pred
        )
        x
      }, t = t, whichJ = whichJ)
    }
  } else {
    stop("Super Learner code with bounds not written yet")
  }
}
out <- list(
  wideDataList = wideDataList,
  ftimeMod = if (returnModels == TRUE) {
    Qmod
  } else {
    NULL
  }
)
return(out)

